  "في إعلانات ميتا اختر هدف «رسائل واتساب» وضع الرقم نفسه.": "In Meta ads, pick the “WhatsApp messages” goal and use the same number.",
  "اكتب رقم الواتساب بمفتاح الدولة ليُنشأ الرابط والرمز.": "Enter the WhatsApp number with country code to create the link and code.",
  "ضعه في النبذة والإعلانات والمحل وعلى المنتج. من يضغط أو يصوّر يفتح محادثة معك والكلمة مكتوبة، فيكون هو من بدأ، وهذه موافقة.": "Put it in your bio, ads, shop and on the product. Whoever taps or scans opens a chat with you with the keyword typed, so they started it, and that's consent.",
  "ضعه في السيرة والإعلانات والمحل وعلى المنتج. من يضغط أو يصوّر يفتح محادثة معك والكلمة مكتوبة، فيكون هو من بدأ، وهذه موافقة.": "Put it in your bio, ads, shop and on the product. Whoever taps or scans opens a chat with you with the keyword typed, so they started it, and that's consent.",
