  "كل الأصوات (مجلد لكل لهجة) ومعها التقرير بنجومك وملاحظاتك وما فشل وسببه": "All voices (a folder per dialect) with the report of your stars, notes, failures and reasons",
  "الأصوات بأرقام فقط دون أسماء المزوّدين، ومعها ورقة تقييم: أرسلها لأهل اللهجة": "Voices with numbers only, no provider names, plus a rating sheet: send it to native speakers",
  "اللهجة": "Dialect",
  "كل اللهجات": "All dialects",
  "⬇️ نزّل الأصوات مع التقرير (zip)": "⬇️ Download voices with the report (zip)",
  "🎧 نسخة للمقيّمين من أهل اللهجة": "🎧 Copy for native-speaker raters",
  "📋 انسخ التقرير": "📋 Copy report",
  "أسماء الملفات في نسخة المقيّمين أرقام مثل «A1B2-3»، والرقم نفسه موجود في تقريرك بجانب اسم المزوّد. عندما يعيد المقيّمون الورقة، أرسلها هنا مع التقرير.": "File names in the raters' copy are codes like “A1B2-3”, and the same code is next to the provider name in your report. When the raters send the sheet back, send it here with the report.",
  "قيّم الأصوات بالنجوم واكتب ملاحظاتك في «المقارنة» و«الاستنساخ»، وستظهر النتيجة هنا: متوسط كل مزوّد في كل لهجة.": "Rate the voices with stars and write notes in “Compare” and “Clone”; the result appears here: each provider's average per dialect.",
  "قيّم الأصوات بالنجوم واكتب ملاحظاتك في «المقارنة» و«الكلون»، وستظهر النتيجة هنا: متوسط كل مزوّد في كل لهجة.": "Rate the voices with stars and write notes in “Compare” and “Clone”; the result appears here: each provider's average per dialect.",
  "🧬 كلون الصوت": "🧬 Voice clone",
  "🧬 استنساخ الصوت": "🧬 Voice clone",
  "✅ معتمد: {0}": "✅ Approved: {0}",
  "الترتيب (متوسط النجوم · عدد التقييمات)": "Ranking (average stars · number of ratings)",
  "مقارنة اللهجات": "Dialect comparison",
  "كلون الصوت": "Voice clone",
  "استنساخ الصوت": "Voice clone",
  "يحتاج مفتاح ElevenLabs المباشر بصلاحية Dubbing في «المفاتيح».": "Needs a direct ElevenLabs key with Dubbing permission in “Keys”.",
  "ارفع فيديو قصيرًا (حتى ٥ دقائق). سيدبلجه ElevenLabs إلى العربية بصوت المتحدث نفسه، وفي الوقت نفسه تُنشأ نسخة في «الترجمة والدبلجة» تكملها بالأصوات العربية باللهجة التي تختارها. قيّم الاثنين هنا بالنجوم.{0}": "Upload a short video (up to 5 minutes). ElevenLabs dubs it into Arabic in the speaker's own voice, and at the same time a copy is created in “Translation and dubbing” for you to finish with Arabic voices in your chosen dialect. Rate both here with stars.{0}",
  "🌍 ابدأ المقارنة": "🌍 Start comparison",
  "يحتاج مفتاحي ElevenLabs و MiniMax المباشرين في «المفاتيح» (الكلون في ElevenLabs يحتاج اشتراك Starter على الأقل).": "Needs direct ElevenLabs and MiniMax keys in “Keys” (cloning in ElevenLabs needs at least the Starter plan).",
  "يحتاج مفتاحي ElevenLabs و MiniMax المباشرين في «المفاتيح» (الاستنساخ في ElevenLabs يحتاج اشتراك Starter على الأقل).": "Needs direct ElevenLabs and MiniMax keys in “Keys” (cloning in ElevenLabs needs at least the Starter plan).",
  "ارفع عينة صوت واضحة (من ٣٠ ثانية إلى دقيقة كلام دون موسيقى). سننشئ منها نسخة صوتية في ElevenLabs و MiniMax، ويقولان الجملة نفسها.{0}": "Upload a clear voice sample (30 seconds to a minute of speech, no music). We'll make a voice copy in ElevenLabs and MiniMax, and both will say the same sentence.{0}",
  "العينة": "Sample",
  "الجملة التي سيقولونها": "The sentence they'll say",
  "🧬 أنشئ الاستنساخ وقارن": "🧬 Create clone and compare",
  "🧬 أنشئ الكلون وقارن": "🧬 Create clone and compare",
  "راجع قطع كل اللهجات أولًا، ثم قارن الكل مرة واحدة": "Review every dialect's passage first, then compare all at once",
  "لكل لهجة قطعة. راجعها وعدّلها إن أردت، وكل مزوّد يقولها بصوتين. المزوّد الذي لا يدعم اللهجة يظهر مقفلًا فيها. استمع وقيّم بالنجوم، والنتيجة النهائية في تبويب «النتيجة».": "Each dialect has a passage. Review and edit it if you like; each provider says it in two voices. A provider that doesn't support the dialect shows as locked. Listen and rate with stars; the final result is in the “Result” tab.",
  "🎧 قارن في هذه اللهجة": "🎧 Compare in this dialect",
  "📝 راجع كل القطع وقارن كل اللهجات": "📝 Review all passages and compare all dialects",
