  "كل يوم بعدد منشوراته، وكل منشور بشكله وقالبه وفكرته وخطافه. راجعها ثم اعتمدها لتنزل على الأوتوبايلوت.": "Each day with its post count, each post with its format, template, idea and hook. Review it, then approve it to send it to autopilot.",
  "كل يوم بعدد منشوراته، وكل منشور بشكله وقالبه وفكرته وخطافه. راجعها ثم اعتمدها لتنتقل إلى الأوتوبايلوت.": "Each day with its post count, each post with its format, template, idea and hook. Review it, then approve it to send it to autopilot.",
