  "هل تحذف هذا المنافس؟ لن يعود في البحث.": "Delete this competitor? It won't come back in searches.",
  "اسم الشخص": "Person's name",
  "أفاتار لأي شخص: أنت، أو شخص آخر لديك إذنه. يُنشأ من تسجيلات حقيقية له (وجهه وحركته وملابسه وصوته)، لتصنع به فيديوهات بكلام جديد. يمكنك إنشاء أكثر من أفاتار.": "An avatar of anyone: you, or someone whose permission you have. It's built from real recordings (face, motion, clothes and voice) so you can make videos with new words. You can create more than one.",
  "أفاتار لأي شخص: أنت، أو حد آخر معك إذنه. يُنشأ من تسجيلات حقيقية له (وشّه وحركته ولبسه وصوته)، لكي تعمل به فيديوهات بكلام جديد. يمكنك تعمل أكثر من أفاتار.": "An avatar of anyone: you, or someone whose permission you have. It's built from real recordings (face, motion, clothes and voice) so you can make videos with new words. You can create more than one.",
  "هذا أنا، أو لدي إذن صريح من الشخص بإنشاء نسخة منه": "This is me, or I have the person's explicit permission to make a copy of them",
  "هذا أنا، أو معي إذن صريح من الشخص إننا نعمل نسخة منه": "This is me, or I have the person's explicit permission to make a copy of them",
  "＋ أفاتار جديد": "＋ New avatar",
  "أنشئ أفاتارًا جديدًا من اليسار، وسنرافقك خطوة خطوة.": "Create a new avatar on the left and we'll guide you step by step.",
  "أنشئ أفاتار جديد من الشمال، وسنمشي معك خطوة خطوة.": "Create a new avatar on the left and we'll guide you step by step.",
  "🎬 فيديو وأنت تقرأ النص": "🎬 A video of you reading the script",
  "هذا أهم تسجيل: نركّب عليه أي نص جديد لاحقًا، فيكون الوجه والحركة والملابس والمكان لك أنت بالضبط.": "This is the most important recording: we put any new script on it later, so the face, motion, clothes and place are exactly yours.",
  "هذا أهم تسجيل: نركّب عليه أي نص جديد لاحقًا، فالوجه والحركة واللبس والمكان يصبحون الخاصة بك أنت بالضبط.": "This is the most important recording: we put any new script on it later, so the face, motion, clothes and place are exactly yours.",
  "📹 سجّل بالكاميرا (يتحرك النص أمامك)": "📹 Record with the camera (the script scrolls in front of you)",
  "📹 سجّل بالكاميرا (النص يتحرك قدامك)": "📹 Record with the camera (the script scrolls in front of you)",
  "📷 صور من عدة اتجاهات": "📷 Photos from several angles",
  "📷 صور من كذا اتجاه": "📷 Photos from several angles",
  "الصورة الأمامية إلزامية (نصنع منها فيديو إن لم يوجد فيديو قراءة)، والباقي يجعل النسخة أدق.": "The front photo is required (we make a video from it if there's no reading video); the rest makes the copy more accurate.",
  "صورة القدام إجبارية (نعمل منها فيديو إذا لا يوجد فيديو قراية)، والباقي يخلّي النسخة أدق.": "The front photo is required (we make a video from it if there's no reading video); the rest makes the copy more accurate.",
  "🎙️ صوتك تلقائيًا": "🎙️ Your voice automatically",
  "⏹ أوقف واحفظ": "⏹ Stop and save",
  "تسجيل نضيف لصوتك في مكان هادي. يُحفظ لكي استنساخ صوتك (قريب)، ويمكنك تستخدمه كمرجع.": "A clean recording of your voice in a quiet place. Saved for voice cloning (soon), and usable as a reference.",
  "تسجيل نظيف لصوتك في مكان هادئ. يُحفظ لاستنساخ صوتك (قريبًا)، ويمكنك استخدامه مرجعًا.": "A clean recording of your voice in a quiet place. Saved for voice cloning (soon), and usable as a reference.",
  "🏠 أماكن التصوير": "🏠 Filming locations",
  "اسم المكان (المكتب، المطبخ…)": "Place name (office, kitchen…)",
  "صوّر المكان الذي تصوّر فيه فيديوهاتك وهو فارغ. عندما تصوّر فيديو وتختار «صوّرت هنا»، تظهر اللقطات المساندة التي يصنعها البرنامج لك في المكان نفسه.": "Photograph your filming spot while empty. When you film and choose “Filmed here”, the B-roll the app makes of you appears in the same place.",
  "صوّر المكان الذي تصوّر فيه فيديوهاتك وهو فارغ. عندما تصوّر فيديو وتقول «صوّرت هنا»، لقطات الـ B-roll ما البرنامج يعملها بيك تظهر في نفس المكان.": "Photograph your filming spot while empty. When you film and choose “Filmed here”, the B-roll the app makes of you appears in the same place.",
