  "اكتب النص لتقرأه وأنت تسجّل": "Write the script to read while recording",
  "🎥 أنشئ فيديو بالأفاتار": "🎥 Make an avatar video",
  "قل النص الجديد بصوتك (سجّله هنا أو ارفعه)، وسيركّبه البرنامج على شفتيك في فيديو القراءة، أو يجعل صورتك تتكلم. استنساخ الصوت (تكتب النص فيُقال بصوتك) سيُضاف عند ربط خدمة الاستنساخ.": "Say the new script in your voice (record or upload it) and the app syncs it to your lips in the reading video, or makes your photo talk. Voice cloning (type the text and hear it in your voice) comes when the cloning service is connected.",
  "قل النص الجديد بصوتك (سجّله هنا أو ارفعه)، والبرنامج يركّبه على شفتيك في فيديو القراءة، أو يجعل صورتك تتكلم. استنساخ الصوت (تكتب النص وهو يُقال بصوتك) سيُضاف عندما نوصّل خدمة الاستنساخ.": "Say the new script in your voice (record or upload it) and the app syncs it to your lips in the reading video, or makes your photo talk. Voice cloning (type the text and hear it in your voice) comes when the cloning service is connected.",
