  "يقرأ الرد الذكي من عقل العلامة (الهوية والمعرفة والقواعد)، ويُخصم كل رد بنقطة تقريبًا. إن طلب العميل أحدًا من الفريق أو سأل عن شيء غير موجود في العقل، تُحوَّل المحادثة إلى صندوق الرسائل.": "The smart reply reads from the brand brain (identity, knowledge and rules), and each reply costs about a point. If the customer asks for a team member or something not in the brain, the chat moves to the inbox.",
