  "{0} تدخل الصور الفيديو بالترتيب، وتُحفظ في «مكتبة المحتويات ← الصور ← ✨ وُلّد بالنموذج المخصص». يُحفظ تلقائيًا عند توقفك عن الكتابة.": "{0} Images enter the video in order and are saved under “Content library ← Images ← ✨ Made by the custom model”. Saves automatically when you stop typing.",
  "{0} الصور تدخل الفيديو بالترتيب، وتُحفظ في «مكتبة المحتويات ← الصور ← ✨ وُلّد بالنموذج المخصص». يُحفظ تلقائيًا عندما تقف عن الكتابة.": "{0} Images enter the video in order and are saved under “Content library ← Images ← ✨ Made by the custom model”. Saves automatically when you stop typing.",
  "مثلًا: موسيقى هادئة ببيانو وإيقاع خفيف، بأجواء متفائلة": "e.g. calm piano music with light drums, upbeat mood",
