  "إن تُركت فارغة تأتي الموسيقى بلا كلمات.": "If empty, you get instrumental music.",
  "توضع الموسيقى تحت الفيديو، وتُحفظ في «الموسيقى» في المكتبة.": "Music goes under the video and is saved under “Music” in the library.",
  "الموسيقى توضع أسفل الفيديو، وتُحفظ في «الموسيقى» في المكتبة.": "Music goes under the video and is saved under “Music” in the library.",
  "يوضع التعليق على الفيديو، ويُحفظ في «التعليقات الصوتية» في المكتبة.": "The voiceover goes on the video and is saved under “Voiceovers” in the library.",
  "التعليق يوضع على الفيديو، ويُحفظ في «التعليقات الصوتية» في المكتبة.": "The voiceover goes on the video and is saved under “Voiceovers” in the library.",
  "لغات أخرى": "Other languages",
  "النماذج التي تقبل صورًا مرجعية تظهر لها «الصور المرجعية». السعر لكل صورة.": "Models that accept reference images show “Reference images”. Price per image.",
  "النماذج التي تقبل صور مرجع يظهرلها «صور المرجع». السعر لكل صورة.": "Models that accept reference images show “Reference images”. Price per image.",
