  "احفظ الإجابة": "Save answer",
  "هذه معلومة عن العلامة، وليست مهمة مطلوبة منك. إن وافقت: ستُحفظ في «المعرفة»، وسيقرؤها العقل عند كتابة أي نص أو فكرة جديدة. يمكنك تعديل النص قبل الموافقة.": "This is a fact about the brand, not a task for you. If you approve: it's saved to “Knowledge” and the brain reads it when writing any new script or idea. You can edit the text before approving.",
  "هذه معلومة عن العلامة، غير مهمة مطلوب منك تعملها. إذا وافقت: ستُحفظ في «المعرفة»، والعقل سيقرؤها وهو يكتب أي نص أو فكرة جديدة. يمكنك تعدّل النص قبل ما توافق.": "This is a fact about the brand, not a task for you. If you approve: it's saved to “Knowledge” and the brain reads it when writing any new script or idea. You can edit the text before approving.",
