  "يُقطَّع كل مشروع إلى قطع أقل من 15 ثانية، ويُولَّد، ويُنشأ له مونتاج كوتشي، ويُصدَّر، ويُجدول بمنشور مشترك مع المدرب والغلاف قبل النهاية بثانيتين.": "Each project is cut into clips under 15 seconds, generated, given a KOCHI montage, exported and scheduled as a collab with the coach, with the cover 2 seconds before the end.",
  "كل مشروع يُقطّع لقطع أقل من 15 ثانية، ويُولّد، ويُنشأ له مونتاج كوتشي، ويُصدّر، ويتجدول بكولاب مع المدرب والغلاف قبل الآخر بثانيتين.": "Each project is cut into clips under 15 seconds, generated, given a KOCHI montage, exported and scheduled as a collab with the coach, with the cover 2 seconds before the end.",
