  "عدد المنشورات في اليوم، في أفضل الأوقات، من القوالب التي تختارها. يعمل تلقائيًا أو ينتظر موافقتك.": "How many posts a day, at the best times, from the templates you choose. Runs on its own or waits for your approval.",
