  "خطوات ترتّبها بنفسك (اسحب، ضع، قطّع، صدّر) من مكتبة العقل، وكل تشغيل يصنع فيديو جديدًا.": "Steps you arrange yourself (drag, place, cut, export) from the brain library; each run makes a new video.",
