  "🔎 راجع الفيديو واقترح التحسينات": "🔎 Review the video and suggest improvements",
  "صوّر نفسك بالجوال وأنت تتكلم (طولي، والضوء قدامك)، وارفعه. لقطات الـ B-roll البرنامج يعملها تلقائيًا في المونتاج.": "Film yourself talking on your phone (vertical, light in front of you) and upload it. The app makes the B-roll automatically in the montage.",
  "صوّر نفسك بالجوال وأنت تتكلم (طوليًا، والضوء أمامك)، وارفعه. يصنع البرنامج لقطات الـ B-roll تلقائيًا في المونتاج.": "Film yourself talking on your phone (vertical, light in front of you) and upload it. The app makes the B-roll automatically in the montage.",
  "🎙️ الفيديو (أنت تتكلم)": "🎙️ The video (you talking)",
  "في نفس المكان": "in the same place",
  "في المكان نفسه": "in the same place",
  "🪄 الـ B-roll تلقائي: اللقطات التي يجب أن تظهر فيها تُنشأ بالأفاتار{0}، والباقي من فيديوهات ستوك حقيقية. وفي المونتاج يمكنك إزالة أي لقطة أو استبدالها بفيديو من جهازك.": "🪄 Automatic B-roll: shots that need you are made with the avatar{0}, the rest come from real stock videos. In the montage you can remove any shot or replace it with a video from your device.",
  "🪄 الـ B-roll تلقائي: اللقطات التي يجب تظهر فيها تُنشأ بالأفاتار{0}، واللي ليس ضروريًا تأتي من فيديوهات ستوك حقيقية. وفي المونتاج يمكنك تزيل أي لقطة أو تبدّلها بفيديو من جهازك.": "🪄 Automatic B-roll: shots that need you are made with the avatar{0}, the rest come from real stock videos. In the montage you can remove any shot or replace it with a video from your device.",
  "جارٍ جلب الأفاتار…": "Loading avatars…",
  "يجلب الأفاتار…": "Loading avatars…",
  "🪞 من في الفيديو؟": "🪞 Who is in the video?",
  "إذا أنشأت أفاتار في «🪞 الأفاتار» (فيديو وصور من عدة اتجاهات)، يستطيع البرنامج صنع لقطات B-roll به، وبدونه سيستخدم فيديوهات ستوك فقط.": "If you create an avatar in «🪞 Avatar» (video and photos from several angles), the app can make B-roll shots with it; otherwise it uses stock videos only.",
  "إذا عملت أفاتار في «🪞 الأفاتار» (فيديو وصور من كذا اتجاه)، البرنامج يستطيع يعمل لقطات B-roll به. من غيرها سيستخدم فيديوهات ستوك فقط.": "If you create an avatar in «🪞 Avatar» (video and photos from several angles), the app can make B-roll shots with it; otherwise it uses stock videos only.",
