  "هذه ملاحظات على الفيديو كما هو، وفق قواعد الخوارزميات لدينا. إذا أردت تنفيذها، صوّر مرة أخرى وارفع، وإذا كان كافيًا هكذا، أكمل إلى المونتاج.": "These are notes on the video as it is, based on our algorithm rules. To apply them, film again and upload; if it's good enough, continue to the montage.",
  "هذه ملاحظات على الفيديو كما هو، على قواعد الخوارزميات التي لدينا. إذا ستنفذها، صوّر مرة أخرى وارفع. وإذا كفاية هكذا، أكمل للمونتاج.": "These are notes on the video as it is, based on our algorithm rules. To apply them, film again and upload; if it's good enough, continue to the montage.",
