  "يقص السكتات، ويغيّر زاوية الكاميرا كل لقطة، ويضبط الألوان، ويختار ويعمل لقطات الـ B-roll، ويضع التايبوجرافي… (لقطات الأفاتار يمكن تأخذ كم دقيقة)": "Cuts silences, changes the camera angle each shot, adjusts colors, picks and makes B-roll shots, adds typography… (avatar shots can take a few minutes)",
  "يقص السكتات، ويغيّر زاوية الكاميرا في كل لقطة، ويضبط الألوان، ويختار لقطات الـ B-roll ويصنعها، ويضع التايبوجرافي… (قد تأخذ لقطات الأفاتار بضع دقائق)": "Cuts silences, changes the camera angle each shot, adjusts colors, picks and makes B-roll shots, adds typography… (avatar shots can take a few minutes)",
