  "لا يوجد بعد فيديوهات قُسّمت لصورة + مؤثرات": "No videos have been split into picture + sound effects yet",
  "ارفع أي فيديو والبرنامج يقسّمه لـ ٤: 🎬 الصورة بدون صوت، و🗣️ النص، و🎵 الموسيقى، و🔊 المؤثرات. كل جزء تسمعه تلقائيًا وتنزّله.": "Upload any video and it gets split into 4: 🎬 the picture without sound, 🗣️ speech, 🎵 music and 🔊 sound effects. Listen to or download each part on its own.",
  "＋ فيديو للتقسيم": "＋ Video to split",
  "ارفع فيديو من «＋ فيديو للتقسيم» لكي نبدأ.": "Upload a video with \"＋ Video to split\" to start.",
