  "هذا الفيديو رُفع قبل التقسيم الجديد. اضغط «🎚️ قسّم آخر» أعلى لكي يُقسّم لصورة ونص وموسيقى ومؤثرات.": "This video was uploaded before the new split. Press \"🎚️ Split again\" above to split it into picture, speech, music and sound effects.",
  "🎧 الفيديو الذي أعلى يشغّل التراكات المفصولة: اضغط 🔊 بجانب أي جزء لكي تقفله وتسمع الباقي تلقائيًا.": "🎧 The video above plays the separated tracks: press 🔊 next to any part to mute it and hear the rest on its own.",
