  "بدون ذكاء اصطناعي: الحركات بالقواعد، والأيقونات من القاموس فقط، والنص يتفرّغ على الخادم إذا متفعّل": "Without AI: moves by rules, icons from the dictionary only, and speech is transcribed on the server if enabled",
