  "أسرع (720)": "Faster (720)",
  "المعاينة هنا بنفس الرسم الذي سيظهر في الفيديو. الفيديو يُرسم على الخادم فريم فريم (دقيقة تقريبًا لكل 15 ثانية).": "The preview uses the same drawing as the final video. The video is drawn on the server frame by frame (about a minute per 15 seconds).",
  "عن الفيديو (اختياري): من يتكلم ولمين وماذا الإحساس": "About the video (optional): who speaks, to whom, what feeling",
  "١. 🗣️ النص": "1. 🗣️ Words",
  "اكتب النص (وكل كلمة تأخذ وقت تقريبي)، أو ارفع صوت أو فيديو والنص يُكتب بتوقيته. إذا رفعت فيديو، التايبوجرافي يتركب فوقه.": "Type the words (each word gets an estimated time), or upload audio or video and the words are transcribed with timing. With a video, the typography goes on top of it.",
