  "✂️ الفيديو قُسّم. اختر أنت تريد تُخرج ماذا منه (كل شيء تلقائيًا، والأسرع المخطط فقط):": "✂️ The video is split. Choose what to extract (each on its own; the schema alone is fastest):",
