  "يقسّم الفيديو مرة أخرى؟ (العناصر الخاصة باللقطات القديمة ستروح، وإذا تريدها اضغط «🧩 العناصر» بعدها)": "Split the video again? (the old shots' elements will be lost; press “🧩 Elements” afterwards if you want them)",
