  "إذا تستخدم ChatGPT: الصق الوصف، وارفع معه صور الشعار والشاشات التي في الوصف، ثم ارفع الصورة التي يطلّعها هنا. البرنامج يقطّعها تلقائيًا.": "With ChatGPT: paste the prompt, attach the logo and screens it mentions, then upload the image it makes here. The app slices it itself.",
