  "🎞️ فُتح في مونتاج الإعلانات. النص العربية: «📋 انسخ النص بتوقيته» وأضفه هناك": "🎞️ Opened in the ads editor. For the Arabic text: “📋 Copy the text with timings” and add it there",
  "✅ تغيّر. الأوصاف حُدّثت؛ ارسم الورقة مرة أخرى لكي يأخذ به": "✅ Changed. Prompts updated; redraw the sheet to apply it",
  "النموذج يشاهد الفيديو كله ويُخرج مخططه: تيمبليت كامل تعمل عليه فيديوهات لعملاء آخرين": "The model watches the whole video and extracts its schema: a full template for other clients' videos",
  "التيمبليت = مخطط فيديو احترافي كامل. البرنامج يملاه بمحتوى العميل، ويرسم كل اللقطات في ورقة واحد لكي تظهر متسقة، والفيديو يُولّد لقطة واحدة متصلة.": "A template is a full professional video schema. The app fills it with the client's content, draws all shots in one sheet so they stay consistent, and generates the video as one continuous take.",
