  "✨ طبّق التعديلات على الفريمات (": "✨ Apply the edits to the frames (",
  "مشهد)": "scenes)",
  "النموذج يقرر لكل مشهد: يبدّل النص الذي على الشاشة فقط، ولا يرسم المشهد من جديد إذا معناه تغيّر.": "The model decides per scene: swap only the on-screen text, or redraw the scene if its meaning changed.",
  "⬆ ارفع تعليق صوتي كامل": "⬆ Upload a full voice-over",
  "كل مشهد (والموصل الذي بعده) يأخذ طول جملته، وجملة كل مشهد تبدأ مع أوله. إذا مشهد طوله تغيّر كثير، حركته تُولّد مرة أخرى وده يظهر في ثمن «ولّد». التسجيل الكامل يجب يكون نفس نص جمل التعليق الصوتي الذي أعلى لكي يُقطّع صحيح.": "Each scene (with the connector after it) takes the length of its line, and each line starts with its scene. If a scene's length changes a lot, its motion is regenerated, which shows in the Generate cost. A full recording must say the same voice-over lines as above to be split correctly.",
  "اكتب تريد تعدّل ماذا في النص": "Write what to change in the script",
  "✍️ النص عُدّل. راجعه، ثم «✨ طبّق التعديلات على الفريمات»": "✍️ Script updated. Review it, then “✨ Apply the edits to the frames”",
  "كله بالصوت الجديد": "entirely with the new voice",
  "يولّد التعليق الصوتي{0}؟ (رخيص، ويُحسب على Atlas)": "Generate the voice-over{0}? (cheap, charged on Atlas)",
  "تزيل التعليق الصوتي؟ (المشاهد تظل بطولها الحالي)": "Remove the voice-over? (scenes keep their current lengths)",
  "فيه {0} مشهد النص الخاص به تغيّر والفريمات ما زال على القديم. تُكمل بدون «✨ طبّق التعديلات على الفريمات»؟": "{0} scenes have script changes but their frames are still the old ones. Continue without “✨ Apply the edits to the frames”?",
  "فيه جمل في التعليق الصوتي تغيّرت وصوتها ما زال القديم. تُكمل؟": "Some voice-over lines changed and their audio is still the old one. Continue?",
  "⬆ يرفع التعليق الصوتي...": "⬆ Uploading the voice-over...",
