  "⏳ وُضع في الدور: سيُرسم أول ما الذي يعمل ينتهي": "⏳ Queued: it will be drawn as soon as the current job finishes",
  "احذفها": "Delete it",
  "مثلًا: الشعار الذي استخدمته خطأ، ضع الشعار الذي في الصورة": "e.g. the logo you used is wrong, use the logo in the image",
