  "📎 ارفع صورة": "📎 Upload an image",
  "علّم على الصورة الصحيح (الشعار مثلًا) واكتب الملاحظة، ثم اضغط ↻ على الفريم الذي تريد تصلّحه. الصور التي معلّم عليها تُرسل للنموذج ويستخدمها كما هي بالضبط.": "Select the correct image (the logo, for example) and write the note, then press ↻ on the frame you want to fix. Selected images are sent to the model and used exactly as they are.",
