  "البرنامج يكتب خطة على مقاس اللقطتين (مجانًا تقريبًا)، تراجعها وتعدّلها، ثم يولّد: صور مفتاحية للمراحل، وحركة بين كل صورتين بموديل فيديو يأخذ صورة بداية وصورة نهاية، ويجمّع آخر A ← الموصل ← أول B.": "The app writes a plan for the two shots (almost free); you review and edit it, then it generates: keyframes for the stages, motion between each pair of images with a start/end-frame video model, and assembles end of A → connector → start of B.",
  "🔁 إعادة بناء (نفس المكان في الفيديو الأصلي: نقارن بالأصلي)": "🔁 Rebuild (same spot in the original video: compare with the original)",
