  "ينتظر...": "Waiting...",
  "هذا الفيديو فُكّك قبل خطوة الموصلات. اضغط «↻ ابحث مرة أخرى» أعلى.": "This video was deconstructed before the connectors step. Press “↻ Search again” above.",
  "لماذا؟ (مثلًا: هذا قطع عادي غير كونيكتور)": "Why? (e.g. this is a plain cut, not a connector)",
  "🧪 الوصفة (تُطبّق على أي مشهدين، سطر لكل خطوة)": "🧪 Recipe (applies to any two scenes, one step per line)",
  "النموذج لم يجد موصلات في هذا الفيديو.": "The model found no connectors in this video.",
  "يشاهد الفيديو مرة أخرى ويبحث عن موصلات. ما قبلته أو رفضته يظل": "Watches the video again for connectors. Whatever you accepted or rejected stays",
  "↻ ابحث مرة أخرى": "↻ Search again",
  "الموصل = لحظة القصة فيها تتحوّل للمشهد الذي بعده أمام عينك بدون قطع (زووم داخل شيء، الخلفية تصبح عالم آخر، الماوس يودّينا لمكان...). النموذج يشاهد الفيديو كله ويكتب لكل واحد وصفته: الشرارة، واللي يظل ثابت، وماذا يتحول لإيه، والكاميرا والإيقاع. ✅ يدخل المكتبة بوصفته وفريماته.": "A connector is a moment where the story turns into the next scene before your eyes, without a cut (zooming into something, the background becoming another world, the cursor taking us somewhere...). The model watches the whole video and writes each one's recipe: the trigger, what stays fixed, what turns into what, the camera and the rhythm. ✅ adds it to the library with its recipe and keyframes.",
  "📚 الموصل حُفظ في المكتبة بوصفته": "📚 The connector was saved to the library with its recipe",
  "تحذف كل الموصلات التي التُقطت في هذا الفيديو (حتى الذي قبلتها أو رفضتها) ويبحث من أولًا؟ ما في المكتبة يظل فيها.": "Clear every connector found in this video (including accepted and rejected ones) and search from scratch? What's in the library stays.",
  "قسّم الجزء هنا (عند {0})": "Split the piece here (at {0})",
  "تقسم الجزء {0} عند {1}؟": "Split piece {0} at {1}?",
  "🔀 قسّم على كل تغيير (تجريبي)": "🔀 Split on every change (experimental)",
  "يحذف كل الاقتراحات ويقترح من الصفر": "Clears every suggestion and suggests from scratch",
  "🗑️ احذف واقترح من جديد": "🗑️ Clear and suggest from scratch",
  "تحذف كل اقتراحات الكومبوننتس (حتى الذي قبلتها أو رفضتها) ويقترح من الصفر؟": "Clear all component suggestions (including accepted and rejected ones) and suggest from scratch?",
  "ما حُفظ في المكتبة يظل فيها، وأسباب الرفض تظل محفوظة لكي النموذج يتعلم منها.": "Whatever was saved to the library stays there, and rejection reasons are kept so the model learns from them.",
  "🗑️ احذف المكتبة كلها": "🗑️ Clear the whole library",
  "تحذف كل الأصول الذي في المكتبة ({0}) بكل نسخها؟ لا يوجد رجوع.": "Delete all assets in the library ({0}) with all their variants? This can't be undone.",
  "متأكد؟ المكتبة ستصبح فارغة. (الفيديوهات التي في المعمل لن تُحذف، والكومبوننتس الذي كنت قبلتها ستعود «ما زال» ويمكنك تقبلها مرة أخرى)": "Are you sure? The library will be empty. (Videos in the lab are kept, and components you accepted go back to “pending” so you can accept them again)",
  "🗑️ حُذف {0} أصل. المكتبة فارغة": "🗑️ Deleted {0} assets. The library is empty",
  "إذا البرنامج فوّت تغيير: اختر فريم من الشريط (أو أوقف الفيديو عند المكان) واضغط هنا": "If the app missed a change: pick a frame from the strip (or pause the video there) and press here",
  "✂️ قسّم هنا": "✂️ Split here",
  "اختر الفريم الذي التغيير يبدأ لديه من الشريط، أو أوقف الفيديو الخاص بالجزء لديه": "Pick the frame where the change starts from the strip, or pause the piece's video there",
  "تقسم الجزء عند {0}؟ (العناصر تتحلل للحتتين من جديد)": "Split the piece at {0}? (Elements are analyzed again for both pieces)",
  "لا يوجد قطع هنا: الحركة وقفت وبدأت حركة جديدة في نفس المشهد": "No cut here: the motion paused and a new motion started in the same scene",
  "🔀 تغيير داخل المشهد": "🔀 Change within the scene",
  "إذا هذه الجزء واللي بعدها حركة واحدة": "If this piece and the next are one motion",
  "🔗 ادمج مع ما بعدها": "🔗 Merge with the next",
  "🔗 دُمجوا. إذا تريد الكومبوننتس تُضبط عليهم اضغط «↻ اقترح مرة أخرى»": "🔗 Merged. To fit the components to them, press “↻ Suggest again”",
  "تقسّم الفيديو من جديد على كل تغيير داخل المشهد؟ (العناصر والكومبوننتس يُنشأ من جديد بعدها)": "Split the video again on every change within a scene? (Elements and components are redone after it)",
  "تقسّم الفيديو من جديد على القطعات فقط؟ (العناصر والكومبوننتس يُنشأ من جديد بعدها)": "Split the video again on cuts only? (Elements and components are redone after it)",
  "البرنامج يقسم الفيديو كيف": "How the app splits the video",
  "🔀 قسّم على كل تغيير": "🔀 Split on every change",
  "✂️ القطعات فقط": "✂️ Cuts only",
  "✂️ قسّم آخر": "✂️ Split again",
  "اضغط على التصميم الذي يعجبك يُختار للكاروسيل (وضغطة أخرى تلغيه). البرنامج يأخذ التقسيم والشكل ويلوّنه بألوان العميل ويضع كلامنا.": "Click the design you like to use it for the carousel (click again to clear). The app takes its layout and look, recolors it with the client's colors and puts our text.",
  "اضغط على الأسلوب يُختار (وضغطة أخرى تلغيه). البرنامج يأخذ طريقة الرسم فقط ويرسم شخصيات جديدة بألوان العميل.": "Click a style to pick it (click again to clear). The app takes only the drawing style and draws new characters in the client's colors.",
  "له مناسب للعلامة": "Why it fits the brand",
