  "🎞️ الموشن جرافيك في المشهد (نسخة العلامة)": "🎞️ Motion graphics in the scene (brand version)",
  "لا يوجد بعد اقتراح. اضغط «التالي: اكتب الاقتراح» أسفل التحليل.": "No proposal yet. Press “Next: write the proposal” under the analysis.",
