  "لا يوجد إشارة ما زال: الرسم لن يأخذ صور من ملف العميل هذه للقطة.": "No mentions yet: the drawing won't use images from the client profile for this shot.",
  "＋ إشارة من ملف العميل": "＋ Mention from the client profile",
