  "👤 اعتمد الكل وأضفهم لملف العميل": "👤 Approve all and add them to the client profile",
  "عندما تعتمد، الصورة تُحفظ في 👤 ملف العميل باسمها، وأوصاف الستوري بورد تعمل لها إشارة (@الاسم) فصورتها الحقيقية تُرسل مع الرسم في كل لقطة.": "When you approve, the image is saved in 👤 the client profile under its name, and storyboard prompts mention it (@name) so its real image is sent with every shot's drawing.",
  "من ملف العميل": "From the client profile",
  "👤 اعتمد وأضفه لملف العميل": "👤 Approve and add to the client profile",
  "✅ حُفظ في ملف العميل ورُبط باللقطات": "✅ Saved to the client profile and linked to the shots",
  "🧠 من ملف العميل": "🧠 From the client profile",
  "تبدأ التنفيذ من جديد من الاقتراح الحالي؟ هذا التنفيذ (صوره وفيديوهاته) سيُحفظ ويمكنك ترجعه بزرار «استعد التنفيذ السابق».": "Restart production from the current proposal? This production (its images and videos) is kept and you can bring it back with “Restore previous production”.",
  "🧠 وُضع {0} مكون من ملف العميل (شاشات / شعار / منتج)": "🧠 Placed {0} components from the client profile (screens / logo / product)",
