  "تحذف العميل «{0}» بكل شاشاته ولوجوهاته؟ (إعلاناته وكاروسيلاته تروح لأقدم عميل)": "Delete the client «{0}» with all its screens and logos? (Its ads and carousels move to the oldest client)",
