  "العميل الذي قيد العمل (اضغط تغيّره)": "The client you're working on (click to change)",
  "يضع شاشات التطبيق والشعار وصور المنتج الحقيقية من ملف العميل مكان المكونات": "Puts the real app screens, logo and product images from the client profile in place of the components",
  "يكتب وصف كل لقطة من جديد ويعمل إشارة (@) للأبطال والمكونات التي في ملف العميل، ثم يرسم بصورهم": "Rewrites every shot's prompt with mentions (@) of the characters and components in the client profile, then draws with their images",
