  "هنا كل شيء عن العميل: منتجه ومجاله وسوقه ولغته وشاشاته ولوجوهاته. البرنامج يستنبط منها الألوان والثيم، وأي كاروسيل أو ستوري بورد أو فيديو يستخدمهم بالضبط بدل ما يخترع.": "Everything about the client: product, field, market, language, screens and logos. The app infers colors and theme from them, and every carousel, storyboard or video uses them exactly instead of inventing.",
  "＋ عميل جديد": "＋ New client",
  "السوق": "Market",
  "لبس محتشم دائمًا": "Always modest clothing",
  "لا": "No",
  "نعم": "Yes",
  "قواعد يجب تتراعى في أي محتوى": "Rules for all content",
  "أسلوب الرسم للكاروسيل (بالإنجليزية أحسن)": "Carousel illustration style (English works best)",
  "👤 العملاء": "👤 Clients",
  "كل عميل له هويته (الاسم والجمهور والسوق واللغة والألوان والخط والشعار) وأصوله، وإعلاناته وكاروسيلاته ومسلسلاته. البرنامج كله يشتغل على العميل الذي مختاره. مكتبة الأصول ومعمل التفكيك مشتركين بين كل العملاء.": "Each client has its own identity (name, audience, market, language, colors, font and logo), assets, ads, carousels and series. The whole app works on the selected client. The asset library and the breakdown lab are shared by all clients.",
  "✏️ ملف العميل الحالي": "✏️ Current client profile",
  "🎨 هوية العميل البصرية والنماذج": "🎨 Client visual identity and models",
  "لبس محتشم في كل الصور والفيديوهات": "Modest clothing in every image and video",
  "قواعد يجب تتراعى": "Rules to follow",
  "أول شعار في ملف العميل (وهو نفسه شعار المونتاج).": "The first logo in the client profile (also the montage logo).",
