  "⏱️ = الوقت ضُبط على بداية الصوت الذي قيست بالكود (دقة 10 مللي ثانية). ▶️ يشغّل الصوت تلقائيًا ويودّي الفيديو للحظته. فصل التراكات نفسها (ملف للكلام وملف للمؤثرات) يحتاج خدمة خارجية، وسنضيفها عندما تختارها.": "⏱️ = the time was snapped to a sound onset measured in code (10 ms precision). ▶️ plays the sound on its own and jumps the video to that moment. Separating the actual tracks (a file for speech, one for effects) needs an external service; we'll add it once you choose one.",
