  "ارفع أي فيديو والبرنامج يفككه: اللقطات، النص والموسيقى والمؤثرات الصوتية، وكل عنصر في كل لقطة ويعمل ماذا ومتى. وأنت تراجع وتقيّم كل شيء ✅ ❌.": "Upload any video and the app breaks it down: shots, speech, music and sound effects, and every element in every shot with what it does and when. You review and rate everything ✅ ❌.",
