  "✨ مكتبة الافيكتس": "✨ Effects library",
  "كل افيكت = حركة + صوتها مربوطين ببعض (الكتابة حرف حرف تظهر بكليك مع كل حرف، العداد يتكتك ويرن في الآخر...). اكتب النص، اختر الشكل، واضغط «▶️ معاينة» على أي افيكت تشوفه وتسمعه. نفس هذه الافيكتس موجودة في «✨ الموشن المتركب» في كل لقطة.": "Each effect = a motion with its sound bound to it (typing letter by letter clicks with every letter, the counter ticks and dings at the end...). Write the text, pick the look, and click “▶️ Preview” on any effect to see and hear it. The same effects are available in “✨ Composited motion” in every shot.",
