  "العناصر والنص يتطبعون أعلى الفيديو بحركتهم. اسحب أي عنصر في المعاينة لكي تغيّر مكانه. اللقطات التي لها موشن متركب الستوري بورد والفيديو توعها يترسمون بدون الجرافيك.": "Elements and text are printed over the video with their motion. Drag any element in the preview to move it. Shots with composited motion get their storyboard and video drawn without graphics.",
