  "الطبقات الحالية ستُستبدل بخطة جديدة من الإعلان الأصلي. تُكمل؟": "The current layers will be replaced by a new plan from the original ad. Continue?",
  "نص جديد": "New text",
  "يركّب طبقات الموشن على فيديو كل لقطة لها طبقات وفيديو خلصان. كل لقطة تأخذ نسخة جديدة «✨ موشن» والأصل يظل. تُكمل؟": "Composites the motion layers onto every shot that has layers and a finished video. Each shot gets a new “✨ Motion” take and the original stays. Continue?",
