  "يضع شاشات التطبيق والشعار وصور المنتج الحقيقية من عقل الإعلان مكان المكونات": "Puts the real app screens, logo and product images from the ad brain into the components",
  "مثلًا: لياقة وتغذية": "e.g. fitness and nutrition",
  "مثلًا: الشعار دائمًا في الآخر، بدون وعود صحية مبالغ فيها": "e.g. logo always at the end, no exaggerated health claims",
  "🧠 عقل الإعلان": "🧠 Ad brain",
  "🧠 طبّق عقل الإعلان": "🧠 Apply ad brain",
  "المنتج الذي الإعلان عنه": "Product this ad is for",
  "🧠 افتح عقل الإعلان": "🧠 Open ad brain",
  "هنا كل شيء عن المنتج: نوعه ومجاله وشاشاته ولوجوهه. البرنامج يستنبط منها الألوان والثيم، وأي ستوري بورد أو فيديو يستخدم الشاشات هؤلاء والشعار بالضبط بدل ما يخترع.": "Everything about the product: its type, field, screens and logos. The app infers the colors and theme from them, and every storyboard or video uses these exact screens and logos instead of inventing.",
  "المنتج": "Product",
  "＋ منتج جديد": "＋ New product",
