  "⬆ ارفع صور": "⬆ Upload images",
  "🎨 الهوية المستنبطة": "🎨 Inferred identity",
  "🔍 استنبط من الصور": "🔍 Infer from images",
  "تُكتب تلقائيًا من الشعار والشاشات، ويمكنك تعدّلها (ما تعدّله بنفسك لا يتغير عندما تستنبط مرة أخرى).": "Filled in automatically from the logo and screens; you can edit it (what you edit by hand isn't changed when you infer again).",
  "الثيم": "Theme",
  "الخطوط": "Typography",
  "شكل الواجهة (بالإنجليزية للبرومبتات)": "UI look (English, for prompts)",
  "وصف الشعار": "Logo description",
  "🎞️ يستحضر الموشن جرافيك من الإعلان الأصلي: لقطة {0}": "🎞️ Bringing in motion graphics from the original ad: shot {0}",
  "⏳ يستحضر الموشن...": "⏳ Bringing in motion...",
  "🎞️ استحضر الموشن من المشهد الأصلي": "🎞️ Bring in motion from the original scene",
  "يشاهد كل مشهد في الإعلان الأصلي ويستحضر الموشن جرافيك الخاص به في اللقطة المقابلة (الموشن المكتوب + عناصر الموشن كمكونات). الموشن المكتوب الآن سيُستبدل، والمكونات الموجودة لن تُلمس. تُكمل؟": "It watches each scene of the original ad and brings its motion graphics into the matching shot (motion text + motion elements as components). The current motion text will be replaced; existing components won't be touched. Continue?",
  "🎞️ استحضر الموشن جرافيك": "🎞️ Bring in motion graphics",
  "⚠️ هذا الاقتراح مبني على تحليل أقدم، فالموشن جرافيك الجديد غير فيه. سيُكتب من جديد بالموشن ثم يُؤخذ للتنفيذ.": "⚠️ This proposal is based on an older analysis, so the new motion graphics aren't in it. It will be rewritten with the motion and then taken to production.",
  "التالي: حدّث الاقتراح بالموشن وخذه للتنفيذ →": "Next: update the proposal with the motion and take it to production →",
  "⚠️ التحليل أو الموشن جرافيك تغيّرون بعد ما الاقتراح كُتب، فاللقطات هنا ماشية على النسخة القديمة.": "⚠️ The analysis or motion graphics changed after the proposal was written, so these shots follow the old version.",
  "↻ حدّث الاقتراح بالموشن وخذه للتنفيذ": "↻ Update the proposal with the motion and take it to production",
