  "لا يوجد بعد اقتراح. اضغط «التالي: اكتب اقتراح كوتشي» أسفل التحليل.": "No proposal yet. Press “Next: write the KOCHI proposal” under the analysis.",
  "تحلل الإعلان من أولًا؟ التعديلات التي عملتها على التحليل ستُحذف. الاقتراح الحالي سيظل حتى ما تضغط «التالي» لكي يُكتب من التحليل الجديد.": "Re-analyze the ad from scratch? Your edits to the analysis will be lost. The current proposal stays until you press “Next” to rewrite it from the new analysis.",
