  "اضغط «⏱️ رقّم الجمل على الصوت»: البرنامج سيسمع الصوت ويقسّمه جمل بتوقيتها (حتى بدون نص).": "Press “⏱️ Time lines on the audio”: the audio is transcribed and split into timed lines (even without a script).",
  "ارفع التعليق الصوتي أولًا.": "Upload the voice-over first.",
  "حاول مرة أخرى (إذا الطلب أُرسل يُكمل بدون دفع آخر)": "Retry (if already submitted, it resumes without paying again)",
  "📝 نسخة {0} من النص": "📝 Script version {0}",
  "لا يوجد بعد. اضغط «✍️ اكتب الحلقة» والبرنامج يكتبها استكمالًا للحلقات التي فاتت، أو ألصق نص جاهز أسفل.": "Nothing yet. Press “✍️ Write episode” and it will be written as a continuation of earlier episodes, or paste a ready script below.",
  "✍️ عدّل": "✍️ Revise",
  "✍️ اكتب الحلقة": "✍️ Write episode",
