  "تقسيم جديد للحلقة؟ النسخ الذي وُلّدت أو رُفعت ستظل محفوظة أسفل «نسخ محفوظة» ويمكنك تحطها على أي لقطة.": "Split the episode again? Generated or uploaded versions stay under “Saved versions” and can go on any shot.",
  "⏳ النموذج يقسّم الحلقة...": "⏳ The model is splitting the episode...",
