  "🎞️ يجمّع الحلقة...": "🎞️ Assembling the episode...",
  "جهّز اللقطات أولًا.": "Prepare the shots first.",
  "⚠️ {0} لقطة ما زال بدون فيديو، ستظهر سوداء بمدتها. يمكنك تجمّع لكي ترى الإيقاع.": "⚠️ {0} shots have no video yet and will be black for their duration. You can assemble to check the pacing.",
  "كل اللقطات جاهزة. كل لقطة تُقص على مدتها بالضبط من الصوت، والفويس أوفر فوقهم.": "All shots ready. Each is trimmed to its exact duration from the audio, with the voice-over on top.",
  "حُفظت في الفيديوهات الجاهزة، ويمكنك تنشرها من صفحة النشر.": "Saved to finished videos; you can publish it from the Publish page.",
  "المسلسلات": "Series",
  "اسم المسلسل": "Series name",
  "مثلًا: لقطات المشهد 5 أسرع، والإضاءة دافية": "e.g. faster shots in scene 5, warm lighting",
  "⚠️ مفتاح Atlas غير مسجل. ضعه من ⚙️ الإعدادات.": "⚠️ Atlas key is not set. Add it in ⚙️ Settings.",
  "🎭 المسلسلات": "🎭 Series",
  "المسلسل والشخصية": "Series & character",
  "النص والصوت": "Script & audio",
  "اللقطات": "Shots",
  "التجميع": "Assembly",
  "اسم المسلسل (للبرنامج فقط، لا يُقال في الحلقات)": "Series name (internal only, never said in episodes)",
  "دستور المسلسل (الوصف الأساسي: الفكرة، الأسلوب، اللهجة، الممنوعات). يُرسل للنموذج مع كل حلقة": "Series bible (the main prompt: idea, style, dialect, don'ts). Sent to the model with every episode",
  "وصف الشخصية (يُكتب في وصف كل لقطة لكي شكلها يظل ثابت). يظل بالإنجليزية": "Character description (added to every shot prompt to keep the look consistent). English is best",
  "صور الشخصية (تُرسل مع كل لقطة تُولّد)": "Character images (sent with every generated shot)",
  "نموذج اللقطات (من Atlas)": "Shots model (Atlas)",
  "نموذج الفيديو": "Video model",
  "📄 من ملف .txt": "📄 From .txt file",
  "كل مشهد يبدأ بسطر «المشهد 1 — ...»، وجمل التعليق الصوتي بين « ». المدد المكتوبة في النص تتجاهل: الصوت هو المرجع.": "Each scene starts with a line «المشهد 1 — ...», voice-over lines go inside « ». Durations written in the script are ignored: the audio is the reference.",
  "ملاحظات للمخرج (اختياري)": "Director notes (optional)",
  "🎙️ التعليق الصوتي": "🎙️ Voice-over",
  "⬆ ارفع الصوت": "⬆ Upload audio",
  "⏱️ رقّم الجمل على الصوت": "⏱️ Time lines on the audio",
  "الجملة": "Line",
  "تبدأ": "Start",
  "تنتهي": "End",
  "🎬 اللقطات": "🎬 Shots",
  "كل لقطة مدتها قادمة من وقت النص الذي عليها. ولّد نسخ أو ارفع فيديو جاهز، واضغط على النسخة التي تعجبك. الماوس أعلى النسخة يشغّلها.": "Each shot's duration comes from the voice-over over it. Generate versions or upload a ready video, and click the one you like. Hover a version to play it.",
  "📦 نسخ محفوظة (من تقسيمات قديمة)": "📦 Saved versions (from older splits)",
  "🎞️ تجميع الحلقة": "🎞️ Assemble episode",
  "🎞️ جمّع الحلقة": "🎞️ Assemble episode",
  "أنشئ مسلسل جديد من الجنب.": "Create a new series from the side panel.",
  "احذف هذه النسخة": "Delete this version",
  "نسخة {0}": "Version {0}",
  "{0} نسخ:": "{0} versions:",
  "مسح هذه النسخة نهائي؟": "Delete this version permanently?",
  "ترسم نسخة جديدة لكل السلايدات؟ النسخ القديمة ستظل محفوظة ويمكنك ترجعلها.": "Draw a new version of every slide? Old versions stay saved and you can go back to them.",
  "🔄 نسخة جديدة لكل السلايدات": "🔄 New version of all slides",
  "كل نسخة ترسمها تُحفظ أسفل السلايد الخاص بها. اختر النسخة التي تعجبك من كل سلايد، ومش يجب تأخذ كل السلايدات من نفس المرة.": "Every version you draw is saved under its slide. Pick the one you like for each slide; they don't have to come from the same round.",
  "{0} (قديم)": "{0} (old)",
  "لا يوجد {0} ما زال. أضف من 📚 المكتبة.": "No {0} yet. Add some from 📚 Library.",
  "تيمبليتس": "templates",
  "أساليب": "styles",
  "شخصيات": "characters",
  "لا يوجد شخصيات ما زال. أضفها من صفحة الشخصيات.": "No characters yet. Add them on the Characters page.",
  "@{0} سيُكتب بجانب صورته ويُنشأ له تاج في النشر": "@{0} will be written next to them and tagged when publishing",
  "⚠️ هذه الشخصية ليس لها حساب إنستجرام مسجل (أضفه من صفحة الشخصيات)": "⚠️ This character has no Instagram account saved (add it on the Characters page)",
  "اضغط على التصميم الذي يعجبك يُختار للكاروسيل (وضغطة أخرى تلغيه). البرنامج يأخذ التقسيم والشكل ويلوّنه بألوان كوتشي ويضع كلامنا.": "Click a design to pick it (click again to remove). Its layout is reused, recolored in KOCHI colors with our text.",
  "البرنامج سيعمل فيديو من السلايدات بالموسيقى، ويُحفظ أيضًا في الفيديوهات الجاهزة. التاج في الريل يصبح على الفيديو كله.": "A video is made from the slides with the music, and also saved to finished videos. In a Reel the tag covers the whole video.",
  "الكاروسيل يُنشر صور بمقاس 1080×1350 على إنستجرام. تيك توك لا يقبل كاروسيل صور من هنا، استخدم الريل.": "The carousel is posted as 1080×1350 images on Instagram. TikTok photo carousels aren't supported here, use the Reel.",
